const nw = msg.data.new_state;
const ow = msg.data.old_state;

// 1. Jeśli ow nie istnieje (restart) lub nie ma atrybutów, nic nie wysyłaj.
// Zapobiega to spamowi przy starcie systemu.
if (!nw || !ow || !ow.attributes || !ow.attributes.lekcje) return null;

const newLekcje = nw.attributes.lekcje || [];
const oldLekcje = ow.attributes.lekcje || [];
const imie = nw.attributes.friendly_name.split(': ')[1] || "Dziecko";

// Pobierz dzisiejszą datę w formacie YYYY-MM-DD
const today = new Date().toISOString().split('T')[0];

const statusMap = {
    "ODWOL": "ODWOŁANA ❌",
    "ZAST": "ZASTĘPSTWO 🔁",
    "PRZEN": "PRZENIESIONA 🕒",
    "NIEOB": "NIEOBECNI (Wycieczka/Wyjście) 🚌"
};

let alerty = [];

// Iterujemy po nowych lekcjach
newLekcje.forEach(n => {
    // --- FILTR DATY ---
    // Ignorujemy lekcje, które odbyły się przed dniem dzisiejszym
    if (n.d < today) return;

    // Szukamy tej samej lekcji w starym stanie (po dacie 'd' i godzinie 'g')
    const o = oldLekcje.find(x => x.d === n.d && x.g === n.g);

    // Jeśli status st się zmienił i aktualnie NIE jest pusty
    // oraz nie było go w poprzednim odczycie
    if (o && n.st !== o.st && n.st !== "") {
        const statusOpis = statusMap[n.st] || n.st;
        alerty.push(`📅 ${n.d} | ⏰ ${n.g}\n📖 **${n.p}**\nStatus: ${statusOpis}`);
    }
});

if (alerty.length > 0) {
    msg.payload = {
        data: {
            title: `Zmiana planu: ${imie} 📅`,
            message: `Wykryto zmiany w harmonogramie:\n\n${alerty.join('\\n\\n')}`,
            notification_id: "vultron_plan_alert_" + nw.entity_id.split('.').pop()
        }
    };
    return msg;
}

return null;
